families.transfer_source:
def batch_charge(units, rate):
    if units < 0:
        raise ValueError('negative units')
    amount = (units + rate)
    return amount

families.transfer_check:
def verify(implementation):
    for units, rate in [(0, 3), (7, 11), (1, 5), (300, 17)]:
        assert implementation.batch_charge(units, rate) == units * rate
    try:
        implementation.batch_charge(-1, 5)
    except ValueError:
        pass
    else:
        raise AssertionError('negative units accepted')

families.negative_check:
def verify(implementation):
    assert implementation.batch_charge(7, 2) == 5
    assert implementation.batch_charge(20, 3) == 17

